import { useEffect, useMemo, useRef, useState } from "react";
import {
  ActionIcon, AppShell, Badge, Button, Drawer, Group, Menu, MultiSelect, NavLink, ScrollArea, SegmentedControl, Select, Stack, Stepper, Tabs, TagsInput, Text, TextInput, Textarea, Tooltip, UnstyledButton,
} from "@mantine/core";
import { useForm } from "@mantine/form";
import { useMediaQuery } from "@mantine/hooks";
import { notifications } from "@mantine/notifications";
import { asRichText, contentLimits, plainText, type ContentEntity, type ProjectBlock, type ProjectContent, type RichText, type SiteSettingsContent, type TeamMemberContent } from "../../shared/content-schema";
import { defaultSiteSettings } from "../../shared/default-site-settings";
import { adminApi, type AdminResource, type AdminUser, type RevisionSummary } from "./api";
import { MediaPicker } from "./MediaPicker";
import { ImageCropper } from "./ImageCropper";
import { RichTextField } from "./RichTextField";
import { formatRoute, homeRoute, parseRoute, sameRoute, type Route, type Section, type SitePanel } from "./routing";
import { SeoPreview } from "./SeoPreview";
import { projectSnippet, siteSnippet } from "./seo";
import { diffContent, type FieldChange } from "./diff";
import { sanitiseTags } from "./tags";

type User = { email: string; role: "admin" | "editor" };
/** setFieldValue tipizza il valore sul path testuale: con una chiave generica TypeScript non riesce a risolverlo, quindi lo dichiariamo qui una volta sola. */
type FieldSetter<T> = <K extends keyof T & string>(key: K, value: T[K]) => void;

const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value));
const lines = (value: string) => value.split("\n").map((item) => item.trim()).filter(Boolean);
const slugify = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, contentLimits.project.slug);
const blankProject = (): ProjectContent => ({ slug: "", title: "", subtitle: "", statusLabel: "In corso", dateRange: "", location: "", audience: "", themes: [], cover: "", coverAlt: "", intro: asRichText(""), objective: asRichText(""), blocks: [], outcomes: [], links: [], partners: [], funders: [], relatedSlugs: [] });
const blankTeamMember = (): TeamMemberContent => ({ name: "", role: "", image: "", bio: [asRichText("")], quote: asRichText("") });
const resourceFor = (section: Section): AdminResource => section === "projects" ? "projects" : section === "team" ? "team" : "site";
const statusLabel = (state: ContentEntity["state"]) => state === "published" ? "Pubblicato" : state === "archived" ? "Archiviato" : "Bozza";
const changedSincePublication = (entity?: ContentEntity) => Boolean(entity?.draft && (!entity.published || JSON.stringify(entity.draft) !== JSON.stringify(entity.published)));
const archiveDate = (value: string) => new Intl.DateTimeFormat("it-IT", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value));

function saveLocalEmail(email: string) { window.localStorage.setItem("spazioterzo-dev-email", email.trim().toLowerCase()); window.location.reload(); }

export function App() {
  const [user, setUser] = useState<User | null>(null);
  const initialRoute = useRef(parseRoute(window.location.hash)).current;
  const [section, setSection] = useState<Section>(initialRoute.section);
  const [sitePanel, setSitePanel] = useState<SitePanel>(initialRoute.sitePanel);
  const [editingId, setEditingId] = useState<string | "new" | null>(initialRoute.editingId);
  const [projects, setProjects] = useState<ContentEntity<ProjectContent>[]>([]);
  const [team, setTeam] = useState<ContentEntity<TeamMemberContent>[]>([]);
  const [site, setSite] = useState<ContentEntity<SiteSettingsContent> | null>(null);
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [accessOpen, setAccessOpen] = useState(false);
  const [mobileNavOpened, setMobileNavOpened] = useState(false);
  const [dirty, setDirty] = useState(false);
  const isMobile = useMediaQuery("(max-width: 767px)");
  const isAdmin = user?.role === "admin";
  const activeTeam = team.filter((item) => item.state !== "archived");
  const relatedOptions = useMemo(() => projects
    .filter((project) => project.state !== "archived")
    .map((project) => ({ value: project.slug, label: (project.draft ?? project.published)?.title || project.slug })), [projects]);
  const siteContent = site?.draft ?? site?.published;
  const siteSeoDefaults = { suffix: siteContent?.seo.titleSuffix ?? defaultSiteSettings.seo.titleSuffix, shareImage: siteContent?.seo.shareImage };

  const reload = async (initial = false) => {
    if (initial) setLoading(true);
    try {
      const identity = await adminApi.me();
      const listedProjects = await adminApi.list<ProjectContent>("projects");
      setUser(identity); setProjects(listedProjects);
      if (identity.role === "admin") {
        const [listedTeam, listedSite, listedUsers] = await Promise.all([adminApi.list<TeamMemberContent>("team"), adminApi.list<SiteSettingsContent>("site"), adminApi.users()]);
        setTeam(listedTeam); setSite(listedSite[0] ?? null); setUsers(listedUsers);
      } else { setTeam([]); setSite(null); setUsers([]); if (section !== "projects") { setSection("projects"); setEditingId(null); } }
    } catch (error) {
      setUser(null);
      if (window.localStorage.getItem("spazioterzo-dev-email")) notifications.show({ color: "red", message: error instanceof Error ? error.message : "Accesso non disponibile" });
    } finally { if (initial) setLoading(false); }
  };
  useEffect(() => { void reload(true); }, []);

  const route: Route = { section, editingId, sitePanel };
  const firstSync = useRef(true);
  // L'indirizzo insegue lo stato: refresh, preferiti e link condivisi tornano dove eri.
  useEffect(() => {
    const next = formatRoute(route);
    if (window.location.hash === next) return;
    if (firstSync.current) window.history.replaceState(null, "", next);
    else window.history.pushState(null, "", next);
    firstSync.current = false;
  }, [section, editingId, sitePanel]);

  // Indietro/avanti del browser e indirizzi scritti a mano: stesso guard delle modifiche non salvate.
  useEffect(() => {
    const apply = () => {
      const target = parseRoute(window.location.hash);
      if (sameRoute(target, route)) return;
      if (!confirmLeave()) { window.history.replaceState(null, "", formatRoute(route)); return; }
      setDirty(false);
      const allowed = user?.role === "admin" || target.section === "projects" ? target : homeRoute;
      setSection(allowed.section); setSitePanel(allowed.sitePanel); setEditingId(allowed.editingId);
    };
    window.addEventListener("popstate", apply);
    window.addEventListener("hashchange", apply);
    return () => { window.removeEventListener("popstate", apply); window.removeEventListener("hashchange", apply); };
  }, [section, editingId, sitePanel, dirty, user]);

  // Un indirizzo che punta a un contenuto sparito (archiviato altrove, id sbagliato) non deve lasciare la pagina vuota.
  useEffect(() => {
    if (loading || !user || section === "site" || !editingId || editingId === "new") return;
    const list: ContentEntity[] = section === "projects" ? projects : team;
    if (!list.length || list.some((item) => item.id === editingId)) return;
    notifications.show({ color: "orange", message: "Contenuto non trovato: torno all’archivio." });
    setEditingId(null);
  }, [loading, user, section, editingId, projects, team]);

  useEffect(() => {
    if (!dirty) return;
    const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ""; };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [dirty]);

  const confirmLeave = () => !dirty || window.confirm("Ci sono modifiche non salvate: uscendo vanno perse. Vuoi continuare?");
  const leaveEditor = (run: () => void) => { if (!confirmLeave()) return; setDirty(false); run(); };
  const navigate = (next: Section) => leaveEditor(() => { setSection(next); setEditingId(next === "site" ? "site" : null); setMobileNavOpened(false); });
  const navigateSite = (panel: SitePanel) => { if (section === "site") { setSitePanel(panel); setMobileNavOpened(false); return; } leaveEditor(() => { setSitePanel(panel); setSection("site"); setEditingId("site"); setMobileNavOpened(false); }); };
  const closeEditor = () => leaveEditor(() => setEditingId(null));
  const saved = async (entity: ContentEntity, message = "Bozza salvata.") => { setDirty(false); await reload(); setEditingId(entity.id); notifications.show({ color: "teal", message }); };
  const openEntity = (id: string) => setEditingId(id);
  const archive = async (resource: AdminResource, id: string) => {
    if (!window.confirm("Archiviare questo contenuto? Non sarà più visibile sul sito. Potrai ripristinarlo dal filtro «Archiviati».")) return;
    try { await adminApi.archive(resource, id); setDirty(false); await reload(); setEditingId(null); notifications.show({ color: "orange", message: "Contenuto archiviato." }); }
    catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Archiviazione non riuscita" }); }
  };
  const duplicate = async (item: ContentEntity<ProjectContent>) => {
    const source = item.draft ?? item.published;
    if (!source) return;
    const taken = new Set(projects.map((project) => project.slug));
    const root = source.slug.slice(0, contentLimits.project.slug - 7);
    let slug = `${root}-copia`;
    for (let attempt = 2; taken.has(slug); attempt += 1) slug = `${root}-copia-${attempt}`;
    try {
      const created = await adminApi.save<ProjectContent>("projects", undefined, { ...clone(source), slug, title: `${source.title} (copia)`.slice(0, contentLimits.project.title) });
      await reload();
      setEditingId(created.id);
      notifications.show({ color: "teal", message: "Copia creata come bozza: rinominala prima di pubblicarla." });
    } catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Copia non riuscita" }); }
  };
  const restore = async (resource: AdminResource, id: string) => {
    try { await adminApi.unarchive(resource, id); await reload(); notifications.show({ color: "teal", message: "Contenuto ripristinato come bozza." }); }
    catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Ripristino non riuscito" }); }
  };
  const publish = async (resource: AdminResource, id: string) => {
    try { await adminApi.publish(resource, id); await reload(); notifications.show({ color: "teal", message: "Contenuto pubblicato sul sito." }); }
    catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Pubblicazione non riuscita" }); }
  };
  const move = async (resource: "projects" | "team", item: ContentEntity<ProjectContent | TeamMemberContent>, direction: -1 | 1) => {
    const items = (resource === "projects" ? projects : team).filter((entry) => entry.state !== "archived");
    const index = items.findIndex((entry) => entry.id === item.id); const neighbour = items[index + direction];
    if (!neighbour) return;
    try { await Promise.all([adminApi.order(resource, item.id, neighbour.displayOrder), adminApi.order(resource, neighbour.id, item.displayOrder)]); await reload(); }
    catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Ordine non aggiornato" }); }
  };

  if (loading) return <main className="admin-loading">Caricamento back office…</main>;
  if (!user) return <AccessGate onSubmit={saveLocalEmail} />;

  const currentProject = section === "projects" && editingId && editingId !== "new" ? projects.find((item) => item.id === editingId) : undefined;
  const currentTeam = section === "team" && editingId && editingId !== "new" ? team.find((item) => item.id === editingId) : undefined;
  const editing = editingId !== null;

  return <AppShell navbar={{ width: 258, breakpoint: "sm", collapsed: { mobile: !mobileNavOpened } }} header={{ height: 58, collapsed: !isMobile }} padding={0} className="admin-app-shell">
    <AppShell.Header className="admin-mobile-header"><a href="/#top"><img src="/assets/logo_spazioterzo.svg" alt="Spazio Terzo" /></a><Button variant="subtle" color="dark" size="xs" aria-expanded={mobileNavOpened} aria-controls="admin-navbar" onClick={() => setMobileNavOpened((open) => !open)}>{mobileNavOpened ? "Chiudi" : "Menu"}</Button></AppShell.Header>
    <AppShell.Navbar id="admin-navbar" className="admin-navbar">
      <div className="admin-brand"><a href="/#top" aria-label="Spazio Terzo, home"><img src="/assets/logo_spazioterzo_negative.svg" alt="Spazio Terzo" /></a><Text component="span">Back office</Text></div>
      <ScrollArea className="admin-nav-scroll"><nav aria-label="Gestione contenuti"><NavLink label={<NavLabel name="Progetti" detail={projects.filter((item) => item.state !== "archived").length} />} active={section === "projects"} onClick={() => navigate("projects")} /><NavLink label={<NavLabel name="Persone" detail={`${activeTeam.length}/3`} />} active={section === "team"} disabled={!isAdmin} onClick={() => isAdmin && navigate("team")} /><NavLink label="Sito" active={section === "site"} disabled={!isAdmin} onClick={() => isAdmin && navigateSite(sitePanel)} />{isAdmin && section === "site" && <div className="site-nav-submenu"><UnstyledButton className={sitePanel === "identity" ? "active" : ""} onClick={() => navigateSite("identity")}>Identità e footer</UnstyledButton><UnstyledButton className={sitePanel === "home" ? "active" : ""} onClick={() => navigateSite("home")}>Home</UnstyledButton><UnstyledButton className={sitePanel === "seo" ? "active" : ""} onClick={() => navigateSite("seo")}>SEO e condivisione</UnstyledButton></div>}</nav></ScrollArea>
      <div className="admin-profile"><Text size="xs" lineClamp={1}>{user.email}</Text><Menu position="top-start" width={230}><Menu.Target><UnstyledButton className="profile-trigger"><span>{isAdmin ? "Amministratore" : "Editor · progetti"}</span><b>•••</b></UnstyledButton></Menu.Target><Menu.Dropdown>{isAdmin && <Menu.Item onClick={() => setAccessOpen(true)}>Gestisci accessi</Menu.Item>}<Menu.Item color="red" onClick={() => { window.localStorage.removeItem("spazioterzo-dev-email"); window.location.reload(); }}>Esci dall’ambiente locale</Menu.Item></Menu.Dropdown></Menu></div>
    </AppShell.Navbar>
    <AppShell.Main className="admin-main"><main className="admin-workspace">
      {section !== "site" && !editing && <ArchiveView section={section} items={section === "projects" ? projects : team} isAdmin={Boolean(isAdmin)} teamFull={activeTeam.length >= 3} onNew={() => setEditingId("new")} onOpen={openEntity} onMove={(item, direction) => void move(section, item, direction)} onRestore={(id) => void restore(resourceFor(section), id)} onDuplicate={(item) => void duplicate(item as ContentEntity<ProjectContent>)} onPublish={(id) => void publish(resourceFor(section), id)} onArchive={(id) => void archive(resourceFor(section), id)} />}
      {section === "projects" && editing && <ProjectEditor key={editingId} entity={currentProject} isAdmin={Boolean(isAdmin)} siteSeo={siteSeoDefaults} relatedOptions={relatedOptions.filter((option) => option.value !== currentProject?.slug)} onBack={closeEditor} onSaved={saved} onPublish={publish} onArchive={archive} onDirtyChange={setDirty} />}
      {section === "team" && editing && <TeamEditor key={editingId} entity={currentTeam} teamCount={activeTeam.length} onBack={closeEditor} onSaved={saved} onPublish={publish} onArchive={archive} onDirtyChange={setDirty} />}
      {section === "site" && <SiteEditor key={site?.id ?? "site"} entity={site ?? undefined} activePanel={sitePanel} onSaved={saved} onPublish={publish} onDirtyChange={setDirty} />}
    </main></AppShell.Main>
    <Drawer opened={accessOpen} onClose={() => setAccessOpen(false)} title="Accessi" position="right" size="lg"><UserManagement users={users} currentEmail={user.email} onChanged={async () => { await reload(); notifications.show({ color: "teal", message: "Accesso aggiornato." }); }} /></Drawer>
  </AppShell>;
}

function NavLabel({ name, detail }: { name: string; detail: string | number }) { return <Group justify="space-between" wrap="nowrap"><span>{name}</span><small>{detail}</small></Group>; }

function AccessGate({ onSubmit }: { onSubmit: (email: string) => void }) {
  const form = useForm({ mode: "controlled", initialValues: { email: "editor@spazioterzo.test" }, validate: { email: (value) => /^\S+@\S+\.\S+$/.test(value) ? null : "Inserisci un’email valida" } });
  return <main className="access-gate"><section><img className="access-logo" src="/assets/logo_spazioterzo.svg" alt="Spazio Terzo" /><Text className="eyebrow">Area riservata</Text><h1>Entra nel back office.</h1><Text c="dimmed">In produzione Cloudflare Access invia un codice monouso all’email autorizzata.</Text><form onSubmit={form.onSubmit(({ email }) => onSubmit(email))}><TextInput label="Email di sviluppo" type="email" required maxLength={254} {...form.getInputProps("email")} /><Button type="submit" color="orange">Apri ambiente locale</Button></form></section></main>;
}

type ArchiveEntity = ContentEntity<ProjectContent | TeamMemberContent>;
function ArchiveView({ section, items, isAdmin, teamFull, onNew, onOpen, onMove, onRestore, onDuplicate, onPublish, onArchive }: { section: "projects" | "team"; items: ArchiveEntity[]; isAdmin: boolean; teamFull: boolean; onNew: () => void; onOpen: (id: string) => void; onMove: (item: ArchiveEntity, direction: -1 | 1) => void; onRestore: (id: string) => void; onDuplicate: (item: ArchiveEntity) => void; onPublish: (id: string) => void; onArchive: (id: string) => void }) {
  const form = useForm({ mode: "controlled", initialValues: { query: "", status: "all" } });
  const showArchived = form.values.status === "archived";
  const visible = useMemo(() => items.filter((item) => {
    const matchesStatus = form.values.status === "archived" ? item.state === "archived" : item.state !== "archived" && (form.values.status === "all" || item.state === form.values.status);
    if (!matchesStatus) return false;
    const content = item.draft ?? item.published;
    const title = content && "title" in content ? content.title : content && "name" in content ? content.name : "";
    return `${title ?? ""} ${item.slug}`.toLowerCase().includes(form.values.query.toLowerCase());
  }), [items, form.values.query, form.values.status]);
  const title = section === "projects" ? "Progetti" : "Persone";
  const canCreate = section === "projects" || !teamFull;
  const active = items.filter((item) => item.state !== "archived");
  const counts = { all: active.length, draft: active.filter((item) => item.state === "draft").length, published: active.filter((item) => item.state === "published").length, archived: items.filter((item) => item.state === "archived").length };
  return <section className="archive-view"><header className="view-header"><div><Text className="eyebrow">Archivio</Text><h1>{title}</h1><Text c="dimmed">{section === "projects" ? "Crea, ordina e prepara i progetti prima della pubblicazione." : "La pagina Persone mantiene il collage con un massimo di tre profili."}</Text></div>{canCreate ? <Button color="orange" onClick={onNew}>{section === "projects" ? "Nuovo progetto" : "Nuova persona"}</Button> : <Tooltip label="Il collage pubblico ospita tre profili: archiviane uno per liberare un posto."><span tabIndex={0} className="disabled-cta"><Button color="orange" disabled>Nuova persona</Button></span></Tooltip>}</header>
    <div className="archive-tools"><TextInput placeholder={`Cerca ${title.toLowerCase()}…`} {...form.getInputProps("query")} /><SegmentedControl aria-label="Filtra per stato" value={form.values.status} onChange={(status) => form.setFieldValue("status", status)} data={[{ value: "all", label: `Tutti ${counts.all}` }, { value: "draft", label: `Bozze ${counts.draft}` }, { value: "published", label: `Online ${counts.published}` }, { value: "archived", label: `Archiviati ${counts.archived}` }]} /></div>
    <div className="archive-list">{visible.length ? visible.map((item, index) => { const content = item.draft ?? item.published; const name = content && "title" in content ? content.title : content && "name" in content ? content.name : "Senza titolo"; const note = content && "subtitle" in content ? content.subtitle : content && "role" in content ? content.role : ""; const image = content && "cover" in content ? content.cover : content && "image" in content ? content.image : ""; const hasPendingChanges = changedSincePublication(item); return <div className="archive-row" key={item.id}><UnstyledButton onClick={() => onOpen(item.id)} className="archive-open">{image && <img src={image} alt="" />}<div className="archive-copy"><Text fw={700}>{name || "Senza titolo"}</Text><Text c="dimmed" size="sm" lineClamp={1}>{note}</Text><Text className="archive-updated" size="xs">Modificato {archiveDate(item.updatedAt)}{hasPendingChanges && item.published ? " · modifiche non online" : ""}</Text></div><Badge className={`state state-${item.state}`} variant="light">{item.state === "published" ? "Online" : statusLabel(item.state)}</Badge></UnstyledButton>{isAdmin && <Group gap={0} className="archive-actions">{showArchived ? <Button size="xs" variant="default" onClick={() => onRestore(item.id)}>Ripristina</Button> : <><Menu position="bottom-end" withinPortal><Menu.Target><ActionIcon aria-label={`Altre azioni per ${name || "questo contenuto"}`} variant="subtle" color="dark">•••</ActionIcon></Menu.Target><Menu.Dropdown><Menu.Item onClick={() => onOpen(item.id)}>Apri</Menu.Item>{section === "projects" && <Menu.Item onClick={() => onDuplicate(item)}>Duplica</Menu.Item>}{hasPendingChanges && <Menu.Item onClick={() => onPublish(item.id)}>{item.published ? "Pubblica modifiche" : "Pubblica"}</Menu.Item>}<Menu.Divider /><Menu.Item color="red" onClick={() => onArchive(item.id)}>Archivia</Menu.Item></Menu.Dropdown></Menu><Tooltip label="Sposta su"><ActionIcon aria-label={`Sposta ${name || "elemento"} più in alto`} variant="subtle" color="dark" disabled={index === 0} onClick={() => onMove(item, -1)}>↑</ActionIcon></Tooltip><Tooltip label="Sposta giù"><ActionIcon aria-label={`Sposta ${name || "elemento"} più in basso`} variant="subtle" color="dark" disabled={index === visible.length - 1} onClick={() => onMove(item, 1)}>↓</ActionIcon></Tooltip></>}</Group>}</div>; }) : <div className="empty-state"><h2>{showArchived ? "Nessun contenuto archiviato." : "Nessun contenuto qui."}</h2><p>{showArchived ? "Gli elementi archiviati compariranno qui e potrai riportarli in bozza." : "Prova un’altra ricerca oppure crea il primo elemento."}</p></div>}</div>
  </section>;
}

type EditorFrameProps = { title: string; eyebrow: string; entity?: ContentEntity; resource: AdminResource; isAdmin?: boolean; onBack?: () => void; onSave: () => void; saving: boolean; dirty?: boolean; preview: React.ReactNode; children: React.ReactNode; onPublish?: (resource: AdminResource, id: string) => Promise<void>; onArchive?: (resource: AdminResource, id: string) => Promise<void>; onDirtyChange?: (dirty: boolean) => void };
function EditorFrame({ title, eyebrow, entity, resource, isAdmin = true, onBack, onSave, saving, dirty = false, preview, children, onPublish, onArchive, onDirtyChange }: EditorFrameProps) {
  const [previewOpen, setPreviewOpen] = useState(false); const [revisionsOpen, setRevisionsOpen] = useState(false);
  const notifyDirty = useRef(onDirtyChange); notifyDirty.current = onDirtyChange;
  useEffect(() => { notifyDirty.current?.(dirty); }, [dirty]);
  useEffect(() => () => notifyDirty.current?.(false), []);
  const readyToPublish = Boolean(entity && isAdmin && changedSincePublication(entity) && !dirty);
  const publicationMessage = !entity ? (dirty ? "Salva per creare la bozza" : "Bozza non ancora salvata") : dirty ? "Salva la bozza prima di pubblicare" : changedSincePublication(entity) ? entity.published ? "La bozza più recente non è ancora online" : "Questa bozza non è ancora online" : entity.published ? "Versione online aggiornata" : "Tutto salvato";
  return <section className="editor-view"><header className="editor-header"><div><Button variant="subtle" color="dark" size="compact-sm" onClick={onBack}>← Archivio</Button><Text className="eyebrow">{eyebrow}</Text><h1>{title}</h1></div><Group gap="xs"><Button variant="default" size="sm" onClick={() => setPreviewOpen(true)}>Anteprima</Button><Button color="orange" variant={readyToPublish ? "default" : "filled"} size="sm" onClick={onSave} loading={saving} disabled={Boolean(entity) && !dirty}>{dirty ? "Salva bozza" : entity ? "Bozza salvata" : "Salva bozza"}</Button>{readyToPublish && <Button color="orange" size="sm" onClick={() => void onPublish?.(resource, entity!.id)}>Pubblica modifiche</Button>}{entity && isAdmin && <Menu position="bottom-end"><Menu.Target><ActionIcon variant="default" size="lg">•••</ActionIcon></Menu.Target><Menu.Dropdown><Menu.Item onClick={() => setRevisionsOpen(true)}>Cronologia revisioni</Menu.Item><Menu.Divider /><Menu.Item color="red" onClick={() => void onArchive?.(resource, entity.id)}>Archivia</Menu.Item></Menu.Dropdown></Menu>}</Group></header><div className="editor-status"><Badge className={`state state-${entity?.state ?? "draft"}`} variant="light">{entity?.published ? "Online" : entity ? statusLabel(entity.state) : "Nuova bozza"}</Badge><Text size="xs" c={dirty || !entity || changedSincePublication(entity) ? "orange" : "teal"}>{publicationMessage}</Text>{entity && <Text size="xs" c="dimmed">Ultimo aggiornamento: {new Date(entity.updatedAt).toLocaleString("it-IT")}</Text>}</div><div className="editor-surface">{children}</div>
    <Drawer opened={previewOpen} onClose={() => setPreviewOpen(false)} title="Anteprima bozza" position="right" size="xl"><div className="public-preview">{preview}</div></Drawer>
    {entity && <RevisionDrawer opened={revisionsOpen} onClose={() => setRevisionsOpen(false)} resource={resource} entity={entity} />}
  </section>;
}

function ProjectEditor({ entity, isAdmin, siteSeo, relatedOptions, onBack, onSaved, onPublish, onArchive, onDirtyChange }: { entity?: ContentEntity<ProjectContent>; isAdmin: boolean; siteSeo: { suffix: string; shareImage?: string }; relatedOptions: Array<{ value: string; label: string }>; onBack: () => void; onSaved: (entity: ContentEntity, message?: string) => Promise<void>; onPublish: (resource: AdminResource, id: string) => Promise<void>; onArchive: (resource: AdminResource, id: string) => Promise<void>; onDirtyChange?: (dirty: boolean) => void }) {
  const initial = clone(entity?.draft ?? entity?.published ?? blankProject());
  const form = useForm<ProjectContent>({ mode: "controlled", initialValues: initial, validate: { title: (value) => value.trim() ? null : "Il titolo è obbligatorio", slug: (value) => /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value) ? null : "Usa minuscole, numeri e trattini", subtitle: (value) => value.trim() ? null : "Il sottotitolo è obbligatorio", cover: (value) => value ? null : "Scegli una copertina", coverAlt: (value) => value.trim() ? null : "Il testo alternativo è obbligatorio" } });
  const [saving, setSaving] = useState(false); const [step, setStep] = useState(0); const [slugEdited, setSlugEdited] = useState(Boolean(entity));
  const set = form.setFieldValue as FieldSetter<ProjectContent>;
  const save = form.onSubmit(async (values) => { setSaving(true); try { const saved = await adminApi.save("projects", entity?.id, values, entity?.displayOrder); form.resetDirty(values); await onSaved(saved); } catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Bozza non salvata" }); } finally { setSaving(false); } });
  const setProjectTitle = (title: string) => { set("title", title); if (!slugEdited) set("slug", slugify(title)); };
  const continueProject = () => { if (step === 0) { const missing = [!form.values.title.trim() && "Titolo", (!form.values.slug || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(form.values.slug)) && "Slug URL", !form.values.subtitle.trim() && "Sottotitolo"].filter(Boolean); if (missing.length) { if (!form.values.title.trim()) form.setFieldError("title", "Inserisci un titolo"); if (!form.values.slug || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(form.values.slug)) form.setFieldError("slug", "Controlla lo slug URL"); if (!form.values.subtitle.trim()) form.setFieldError("subtitle", "Aggiungi un sottotitolo"); notifications.show({ color: "orange", message: `Prima completa: ${missing.join(", ")}.` }); return; } } if (step === 1 && (!form.values.cover || !form.values.coverAlt.trim())) { if (!form.values.cover) form.setFieldError("cover", "Scegli una copertina"); if (!form.values.coverAlt.trim()) form.setFieldError("coverAlt", "Inserisci il testo alternativo"); notifications.show({ color: "orange", message: "Prima scegli la copertina e il suo testo alternativo." }); return; } setStep((value) => value + 1); };
  const info = <ProjectInfo value={form.values} set={set} onTitleChange={setProjectTitle} onSlugChange={(slug) => { setSlugEdited(true); set("slug", slug); }} />;
  const images = <ProjectImages value={form.values} set={set} />;
  const story = <ProjectStory value={form.values} set={set} />;
  const connections = <ProjectConnections value={form.values} set={set} relatedOptions={relatedOptions} />;
  const seo = <ProjectSeo value={form.values} set={set} suffix={siteSeo.suffix} shareImage={siteSeo.shareImage} />;
  const newProject = !entity;
  return <form onSubmit={save}><EditorFrame title={entity ? form.values.title || "Progetto senza titolo" : "Nuovo progetto"} eyebrow={entity ? "Modifica progetto" : "Crea progetto"} entity={entity} resource="projects" isAdmin={isAdmin} onBack={onBack} onSave={() => save()} saving={saving} dirty={form.isDirty()} preview={<ProjectPreview project={form.values} />} onPublish={onPublish} onArchive={onArchive} onDirtyChange={onDirtyChange}>
    {newProject ? <><Stepper active={step} onStepClick={setStep} allowNextStepsSelect={false} className="project-stepper"><Stepper.Step label="Base" description="Titolo e contesto">{info}</Stepper.Step><Stepper.Step label="Immagini" description="Cover e accessibilità">{images}</Stepper.Step><Stepper.Step label="Racconto" description="Storia e materiali">{story}{connections}{seo}</Stepper.Step><Stepper.Completed><ReviewProject project={form.values} /></Stepper.Completed></Stepper><Group className="stepper-actions" justify="space-between" mt="xl"><Button variant="default" disabled={step === 0} onClick={() => setStep((value) => value - 1)}>Indietro</Button>{step < 2 ? <Button color="orange" onClick={continueProject}>Continua</Button> : <Button color="orange" loading={saving} onClick={() => save()}>Salva bozza</Button>}</Group></> : <Tabs defaultValue="info" className="editor-tabs"><Tabs.List><Tabs.Tab value="info">Informazioni</Tabs.Tab><Tabs.Tab value="story">Racconto</Tabs.Tab><Tabs.Tab value="connections">Collegamenti</Tabs.Tab><Tabs.Tab value="seo">SEO</Tabs.Tab></Tabs.List><Tabs.Panel value="info">{info}{images}</Tabs.Panel><Tabs.Panel value="story">{story}</Tabs.Panel><Tabs.Panel value="connections">{connections}</Tabs.Panel><Tabs.Panel value="seo">{seo}</Tabs.Panel></Tabs>}
  </EditorFrame></form>;
}

function ProjectInfo({ value, set, onTitleChange, onSlugChange }: { value: ProjectContent; set: FieldSetter<ProjectContent>; onTitleChange: (title: string) => void; onSlugChange: (slug: string) => void }) { return <section className="form-section"><div className="section-heading"><h2>Base</h2><p>Le informazioni essenziali del progetto.</p></div><div className="form-grid"><TextInput label="Titolo" required maxLength={contentLimits.project.title} value={value.title} onChange={(event) => onTitleChange(event.currentTarget.value)} /><TextInput label="Slug URL" description="Si crea dal titolo; puoi modificarlo." required maxLength={contentLimits.project.slug} value={value.slug} onChange={(event) => onSlugChange(event.currentTarget.value)} /><Textarea label="Sottotitolo" required maxLength={contentLimits.project.subtitle} autosize minRows={2} value={value.subtitle} onChange={(event) => set("subtitle", event.currentTarget.value)} /><Select label="Stato" data={["In corso", "Concluso"]} value={value.statusLabel} onChange={(next) => set("statusLabel", (next ?? "In corso") as ProjectContent["statusLabel"])} /><TextInput label="Periodo" maxLength={contentLimits.project.dateRange} value={value.dateRange} onChange={(event) => set("dateRange", event.currentTarget.value)} /><TextInput label="Luogo" maxLength={contentLimits.project.location} value={value.location} onChange={(event) => set("location", event.currentTarget.value)} /><Textarea label="Destinatari" maxLength={contentLimits.project.audience} autosize minRows={2} value={value.audience} onChange={(event) => set("audience", event.currentTarget.value)} /><TagsInput label="Temi" description="Scrivi e premi Invio per ogni tema" placeholder="Aggiungi un tema" maxTags={20} value={value.themes} onChange={(next) => set("themes", sanitiseTags(next, { maxItems: 20, maxLength: contentLimits.project.theme }))} /></div><RichTextField label="Introduzione" maxLength={contentLimits.project.intro} value={value.intro} onChange={(next) => set("intro", next)} /><RichTextField label="Intenzione / obiettivo" maxLength={contentLimits.project.objective} value={value.objective} onChange={(next) => set("objective", next)} /></section>; }
function ProjectImages({ value, set }: { value: ProjectContent; set: FieldSetter<ProjectContent> }) { return <section className="form-section"><div className="section-heading"><h2>Copertina</h2><p>L’immagine apre la pagina del progetto. Il testo alternativo è pubblicato con lei.</p></div><MediaPicker label="Immagine di copertina" required value={{ url: value.cover, alt: value.coverAlt, assetId: value.coverAssetId }} onChange={(next) => { set("cover", next.url); set("coverAlt", next.alt); set("coverAssetId", next.assetId); }} /></section>; }
function ProjectStory({ value, set }: { value: ProjectContent; set: FieldSetter<ProjectContent> }) { return <section className="form-section"><div className="section-heading"><h2>Racconto</h2><p>Costruisci la pagina con blocchi curati, nell’ordine in cui devono apparire.</p></div><BlocksEditor blocks={value.blocks} onChange={(next) => set("blocks", next)} /><Textarea label="Risultati" description="Una riga per risultato" maxLength={contentLimits.project.outcome * 12} autosize minRows={4} value={value.outcomes.join("\n")} onChange={(event) => set("outcomes", lines(event.currentTarget.value))} /></section>; }
function ProjectConnections({ value, set, relatedOptions }: { value: ProjectContent; set: FieldSetter<ProjectContent>; relatedOptions: Array<{ value: string; label: string }> }) { return <section className="form-section"><div className="section-heading"><h2>Collegamenti</h2><p>Link, video, reti e invito finale.</p></div><LinksEditor links={value.links} onChange={(next) => set("links", next)} /><VideoEditor value={value.video} onChange={(next) => set("video", next)} /><div className="form-grid"><TextInput label="Testo CTA" maxLength={contentLimits.project.ctaLabel} value={value.cta?.label ?? ""} onChange={(event) => set("cta", { label: event.currentTarget.value, href: value.cta?.href ?? "" })} /><TextInput label="Link CTA" maxLength={2_000} value={value.cta?.href ?? ""} onChange={(event) => set("cta", { label: value.cta?.label ?? "", href: event.currentTarget.value })} /><TagsInput label="Partner" description="Scrivi e premi Invio per ognuno" placeholder="Aggiungi un partner" maxTags={30} value={value.partners} onChange={(next) => set("partners", sanitiseTags(next, { maxItems: 30, maxLength: contentLimits.project.partner }))} /><TagsInput label="Finanziatori" description="Scrivi e premi Invio per ognuno" placeholder="Aggiungi un finanziatore" maxTags={30} value={value.funders} onChange={(next) => set("funders", sanitiseTags(next, { maxItems: 30, maxLength: contentLimits.project.partner }))} /><MultiSelect label="Progetti correlati" description="Scegli fra i progetti esistenti" placeholder={value.relatedSlugs.length ? undefined : "Nessun progetto collegato"} searchable clearable maxValues={20} data={[...relatedOptions, ...value.relatedSlugs.filter((slug) => !relatedOptions.some((option) => option.value === slug)).map((slug) => ({ value: slug, label: `${slug} — non trovato` }))]} value={value.relatedSlugs} onChange={(next) => set("relatedSlugs", next)} /></div><Textarea label="Nota di visibilità" maxLength={contentLimits.project.visibilityNote} autosize minRows={3} value={value.visibilityNote ?? ""} onChange={(event) => set("visibilityNote", event.currentTarget.value || undefined)} /></section>; }
function ProjectSeo({ value, set, suffix, shareImage }: { value: ProjectContent; set: FieldSetter<ProjectContent>; suffix: string; shareImage?: string }) {
  const snippet = projectSnippet({ slug: value.slug, title: value.title, subtitle: value.subtitle, seoTitle: value.seoTitle, seoDescription: value.seoDescription, suffix });
  return <section className="form-section"><div className="section-heading"><h2>SEO</h2><p>Compila solo se il progetto deve comparire in ricerca con parole diverse dal titolo e dal sottotitolo.</p></div>
    <div className="seo-layout">
      <div className="seo-fields">
        <TextInput label="Titolo SEO" description={`Consigliati meno di 60 caratteri, suffisso «${suffix}» incluso`} maxLength={contentLimits.project.seoTitle} value={value.seoTitle ?? ""} onChange={(event) => set("seoTitle", event.currentTarget.value || undefined)} />
        <FieldCounter length={(value.seoTitle ?? "").length} max={contentLimits.project.seoTitle} />
        <Textarea label="Descrizione SEO" description="Consigliati 120-155 caratteri" maxLength={contentLimits.project.seoDescription} autosize minRows={3} value={value.seoDescription ?? ""} onChange={(event) => set("seoDescription", event.currentTarget.value || undefined)} />
        <FieldCounter length={(value.seoDescription ?? "").length} max={contentLimits.project.seoDescription} />
      </div>
      <SeoPreview snippet={snippet} shareImage={shareImage ?? value.cover} shareAlt={value.coverAlt} />
    </div>
  </section>;
}
function FieldCounter({ length, max }: { length: number; max: number }) { return <Text size="xs" ta="right" c={length > max * .9 ? "orange" : "dimmed"} aria-live="polite">{length}/{max}</Text>; }

function TeamEditor({ entity, teamCount, onBack, onSaved, onPublish, onArchive, onDirtyChange }: { entity?: ContentEntity<TeamMemberContent>; teamCount: number; onBack: () => void; onSaved: (entity: ContentEntity, message?: string) => Promise<void>; onPublish: (resource: AdminResource, id: string) => Promise<void>; onArchive: (resource: AdminResource, id: string) => Promise<void>; onDirtyChange?: (dirty: boolean) => void }) {
  const form = useForm<TeamMemberContent>({ mode: "controlled", initialValues: clone(entity?.draft ?? entity?.published ?? blankTeamMember()), validate: { name: (value) => value.trim() ? null : "Il nome è obbligatorio", role: (value) => value.trim() ? null : "Il ruolo è obbligatorio", image: (value) => value ? null : "Scegli un ritratto" } });
  const [saving, setSaving] = useState(false); const set = form.setFieldValue as FieldSetter<TeamMemberContent>;
  const save = form.onSubmit(async (values) => { setSaving(true); try { const saved = await adminApi.save("team", entity?.id, values, entity?.displayOrder); form.resetDirty(values); await onSaved(saved); } catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Bozza non salvata" }); } finally { setSaving(false); } });
  if (!entity && teamCount >= 3) return <section className="editor-view"><header className="editor-header"><div><Button variant="subtle" color="dark" size="compact-sm" onClick={onBack}>← Archivio</Button><Text className="eyebrow">Persone</Text><h1>Il team è completo</h1></div></header><div className="empty-state"><p>Il collage pubblico è progettato per tre persone. Archivia un profilo prima di aggiungerne un altro.</p></div></section>;
  return <form onSubmit={save}><EditorFrame title={entity ? form.values.name || "Persona senza nome" : "Nuova persona"} eyebrow="Persone" entity={entity} resource="team" onBack={onBack} onSave={() => save()} saving={saving} dirty={form.isDirty()} preview={<TeamPreview member={form.values} />} onPublish={onPublish} onArchive={onArchive} onDirtyChange={onDirtyChange}><section className="form-section"><div className="section-heading"><h2>Profilo</h2><p>{teamCount}/3 profili attivi. L’ordine si gestisce dall’archivio.</p></div><div className="form-grid"><TextInput label="Nome e cognome" required maxLength={contentLimits.team.name} value={form.values.name} onChange={(event) => set("name", event.currentTarget.value)} /><TextInput label="Ruolo" required maxLength={contentLimits.team.role} value={form.values.role} onChange={(event) => set("role", event.currentTarget.value)} /></div><MediaPicker label="Ritratto" required showPreview={false} altEditable={false} altHint="Il testo alternativo si costruisce dal nome inserito qui sopra." value={{ url: form.values.image, alt: `Ritratto di ${form.values.name || "persona del team"}`, assetId: form.values.imageAssetId }} onChange={(next) => { if (next.url === form.values.image && next.assetId === form.values.imageAssetId) return; form.setValues({ ...form.values, image: next.url, imageAssetId: next.assetId, imageCrop: undefined, imagePosition: undefined }); }} /><ImageCropper image={form.values.image} value={form.values.imageCrop} onChange={(imageCrop) => set("imageCrop", imageCrop)} title="Ritaglio del ritratto" description="Sposta il volto nell’area: è esattamente la parte che apparirà sul sito." /><RichTextList label="Bio" maxLength={contentLimits.team.bioParagraph} values={form.values.bio} onChange={(next) => set("bio", next)} /><RichTextField label="Citazione" maxLength={contentLimits.team.quote} value={form.values.quote} onChange={(next) => set("quote", next)} /><TextInput label="Autore citazione" maxLength={contentLimits.team.quoteAuthor} value={form.values.quoteAuthor ?? ""} onChange={(event) => set("quoteAuthor", event.currentTarget.value || undefined)} /></section></EditorFrame></form>;
}

function SiteEditor({ entity, activePanel, onSaved, onPublish, onDirtyChange }: { entity?: ContentEntity<SiteSettingsContent>; activePanel: SitePanel; onSaved: (entity: ContentEntity, message?: string) => Promise<void>; onPublish: (resource: AdminResource, id: string) => Promise<void>; onDirtyChange?: (dirty: boolean) => void }) {
  const form = useForm<SiteSettingsContent>({ mode: "controlled", initialValues: clone(entity?.draft ?? entity?.published ?? defaultSiteSettings) });
  const [saving, setSaving] = useState(false); const [homeSection, setHomeSection] = useState<keyof SiteSettingsContent["home"]>("hero");
  const update = (recipe: (draft: SiteSettingsContent) => void) => { const next = clone(form.values); recipe(next); form.setValues(next); };
  const save = form.onSubmit(async (values) => { setSaving(true); try { const saved = await adminApi.save("site", entity?.id, values); form.resetDirty(values); await onSaved(saved); } catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Bozza non salvata" }); } finally { setSaving(false); } });
  const panelTitle = activePanel === "identity" ? "Identità e footer" : activePanel === "home" ? "Home" : "SEO e condivisione";
  return <form onSubmit={save}><EditorFrame title={panelTitle} eyebrow="Sito" entity={entity} resource="site" onSave={() => save()} saving={saving} dirty={form.isDirty()} preview={<SitePreview site={form.values} />} onPublish={onPublish} onDirtyChange={onDirtyChange}>{activePanel === "identity" ? <SiteIdentity value={form.values} update={update} /> : activePanel === "home" ? <HomeEditor value={form.values} update={update} active={homeSection} onSelect={setHomeSection} /> : <SiteSeo value={form.values} update={update} />}</EditorFrame></form>;
}

function SiteIdentity({ value, update }: { value: SiteSettingsContent; update: (recipe: (draft: SiteSettingsContent) => void) => void }) { return <section className="form-section"><div className="section-heading"><h2>Identità e footer</h2><p>I dati compariranno nell’header, nel footer e nei contatti quando compilati.</p></div><div className="form-grid"><TextInput label="Nome" maxLength={contentLimits.site.organizationName} value={value.identity.organizationName} onChange={(event) => update((draft) => { draft.identity.organizationName = event.currentTarget.value; })} /><TextInput label="Forma giuridica" maxLength={contentLimits.site.legalForm} value={value.identity.legalForm} onChange={(event) => update((draft) => { draft.identity.legalForm = event.currentTarget.value; })} /><TextInput label="Città" maxLength={contentLimits.site.city} value={value.identity.city} onChange={(event) => update((draft) => { draft.identity.city = event.currentTarget.value; })} /><Textarea label="Indirizzo" maxLength={contentLimits.site.address} autosize minRows={2} value={value.identity.address ?? ""} onChange={(event) => update((draft) => { draft.identity.address = event.currentTarget.value || undefined; })} /><TextInput label="Paese" maxLength={contentLimits.site.country} value={value.identity.country} onChange={(event) => update((draft) => { draft.identity.country = event.currentTarget.value; })} /><TextInput label="Email" maxLength={254} value={value.identity.email} onChange={(event) => update((draft) => { draft.identity.email = event.currentTarget.value; })} /><TextInput label="Telefono" maxLength={contentLimits.site.phone} value={value.identity.phone ?? ""} onChange={(event) => update((draft) => { draft.identity.phone = event.currentTarget.value || undefined; })} /></div><MediaPicker label="Logo su sfondo scuro" value={{ url: value.identity.logoLight ?? "", alt: `${value.identity.organizationName} logo chiaro` }} onChange={(next) => update((draft) => { draft.identity.logoLight = next.url || undefined; })} /><MediaPicker label="Logo su sfondo chiaro" value={{ url: value.identity.logoDark ?? "", alt: `${value.identity.organizationName} logo scuro` }} onChange={(next) => update((draft) => { draft.identity.logoDark = next.url || undefined; })} /><SocialLinks value={value.identity.socialLinks} onChange={(next) => update((draft) => { draft.identity.socialLinks = next; })} /></section>; }

function HomeEditor({ value, update, active, onSelect }: { value: SiteSettingsContent; update: (recipe: (draft: SiteSettingsContent) => void) => void; active: keyof SiteSettingsContent["home"]; onSelect: (next: keyof SiteSettingsContent["home"]) => void }) { const labels: Array<[keyof SiteSettingsContent["home"], string]> = [["hero", "Hero"], ["association", "Associazione"], ["origin", "Perché Spazio Terzo"], ["activities", "Attività"], ["territory", "Territorio"], ["imageStatement", "Immagine manifesto"], ["contact", "Contatti"]]; return <section className="form-section"><div className="section-heading"><h2>Home</h2><p>Scegli una sezione: modifichi un blocco alla volta e l’anteprima resta sempre fedele al sito.</p></div><div className="home-editor-layout"><div className="section-map">{labels.map(([key, label]) => <UnstyledButton key={key} className={active === key ? "active" : ""} onClick={() => onSelect(key)}>{label}<span>→</span></UnstyledButton>)}</div><div className="home-fields"><HomeFields value={value} update={update} active={active} /></div></div></section>; }
function HomeFields({ value, update, active }: { value: SiteSettingsContent; update: (recipe: (draft: SiteSettingsContent) => void) => void; active: keyof SiteSettingsContent["home"] }) {
  if (active === "hero") return <Stack><RichTextField label="Titolo" maxLength={contentLimits.site.heroHeadline} value={value.home.hero.headline} onChange={(next) => update((draft) => { draft.home.hero.headline = next; })} /><TextInput label="Metadati" maxLength={contentLimits.site.heroMeta} value={value.home.hero.meta} onChange={(event) => update((draft) => { draft.home.hero.meta = event.currentTarget.value; })} /><TextInput label="CTA" maxLength={contentLimits.site.ctaLabel} value={value.home.hero.ctaLabel} onChange={(event) => update((draft) => { draft.home.hero.ctaLabel = event.currentTarget.value; })} /><MediaPicker label="Immagine hero" value={{ url: value.home.hero.heroImage ?? "", alt: "Immagine hero" }} onChange={(next) => update((draft) => { draft.home.hero.heroImage = next.url || undefined; })} /></Stack>;
  if (active === "association") return <Stack><RichTextField label="Titolo" maxLength={contentLimits.site.associationHeading} value={value.home.association.heading} onChange={(next) => update((draft) => { draft.home.association.heading = next; })} /><RichTextField label="Testo" maxLength={contentLimits.site.associationBody} value={value.home.association.body} onChange={(next) => update((draft) => { draft.home.association.body = next; })} /><TextInput label="CTA" maxLength={contentLimits.site.ctaLabel} value={value.home.association.ctaLabel} onChange={(event) => update((draft) => { draft.home.association.ctaLabel = event.currentTarget.value; })} /><TextInput label="Link CTA" maxLength={2_000} value={value.home.association.ctaHref} onChange={(event) => update((draft) => { draft.home.association.ctaHref = event.currentTarget.value; })} /></Stack>;
  if (active === "origin") return <Stack><TextInput label="Etichetta" maxLength={contentLimits.site.originEyebrow} value={value.home.origin.eyebrow} onChange={(event) => update((draft) => { draft.home.origin.eyebrow = event.currentTarget.value; })} /><RichTextField label="Preludio" maxLength={contentLimits.site.originPrelude} value={value.home.origin.prelude} onChange={(next) => update((draft) => { draft.home.origin.prelude = next; })} /><RichTextField label="Titolo" maxLength={contentLimits.site.originHeading} value={value.home.origin.heading} onChange={(next) => update((draft) => { draft.home.origin.heading = next; })} /><RichTextField label="Testo sinistro" maxLength={contentLimits.site.originStatement} value={value.home.origin.statement} onChange={(next) => update((draft) => { draft.home.origin.statement = next; })} /><RichTextField label="Testo destro" maxLength={contentLimits.site.originIdentity} value={value.home.origin.identity} onChange={(next) => update((draft) => { draft.home.origin.identity = next; })} /></Stack>;
  if (active === "activities") return <Stack><RichTextField label="Titolo sezione" maxLength={contentLimits.site.activitiesHeading} value={value.home.activities.heading} onChange={(next) => update((draft) => { draft.home.activities.heading = next; })} />{value.home.activities.items.map((activity, index) => <div className="activity-edit" key={activity.id}><TextInput label={`Attività ${index + 1}`} maxLength={contentLimits.site.activityTitle} value={activity.title} onChange={(event) => update((draft) => { draft.home.activities.items[index].title = event.currentTarget.value; })} /><RichTextField label="Descrizione" maxLength={contentLimits.site.activityDescription} value={activity.description} onChange={(next) => update((draft) => { draft.home.activities.items[index].description = next; })} /></div>)}</Stack>;
  if (active === "territory") return <Stack><RichTextField label="Titolo" maxLength={contentLimits.site.territoryHeading} value={value.home.territory.heading} onChange={(next) => update((draft) => { draft.home.territory.heading = next; })} /><RichTextField label="Testo" maxLength={contentLimits.site.territoryBody} value={value.home.territory.body} onChange={(next) => update((draft) => { draft.home.territory.body = next; })} /><TextInput label="CTA" maxLength={contentLimits.site.ctaLabel} value={value.home.territory.ctaLabel} onChange={(event) => update((draft) => { draft.home.territory.ctaLabel = event.currentTarget.value; })} /><TextInput label="Link CTA" maxLength={2_000} value={value.home.territory.ctaHref} onChange={(event) => update((draft) => { draft.home.territory.ctaHref = event.currentTarget.value; })} /></Stack>;
  if (active === "imageStatement") return <Stack><MediaPicker label="Immagine manifesto" value={{ url: value.home.imageStatement.image ?? "", alt: value.home.imageStatement.caption || "Immagine manifesto" }} onChange={(next) => update((draft) => { draft.home.imageStatement.image = next.url || undefined; })} /><Textarea label="Didascalia" maxLength={contentLimits.site.imageCaption} autosize minRows={2} value={value.home.imageStatement.caption} onChange={(event) => update((draft) => { draft.home.imageStatement.caption = event.currentTarget.value; })} /><TextInput label="Parola verticale" maxLength={contentLimits.site.verticalWord} value={value.home.imageStatement.verticalWord} onChange={(event) => update((draft) => { draft.home.imageStatement.verticalWord = event.currentTarget.value; })} /></Stack>;
  return <Stack><RichTextField label="Titolo" maxLength={contentLimits.site.contactHeading} value={value.home.contact.heading} onChange={(next) => update((draft) => { draft.home.contact.heading = next; })} /><RichTextField label="Testo" maxLength={contentLimits.site.contactBody} value={value.home.contact.body} onChange={(next) => update((draft) => { draft.home.contact.body = next; })} /><TextInput label="Etichetta email" maxLength={contentLimits.site.emailLabel} value={value.home.contact.emailLabel ?? ""} onChange={(event) => update((draft) => { draft.home.contact.emailLabel = event.currentTarget.value || undefined; })} /></Stack>;
}
function SiteSeo({ value, update }: { value: SiteSettingsContent; update: (recipe: (draft: SiteSettingsContent) => void) => void }) { return <section className="form-section"><div className="section-heading"><h2>SEO e condivisione</h2><p>I metadati predefiniti del sito e l’immagine che appare quando lo condividi.</p></div><SeoPreview snippet={siteSnippet({ suffix: value.seo.titleSuffix, description: value.seo.defaultDescription })} shareImage={value.seo.shareImage ?? ""} shareAlt="Immagine di condivisione del sito" /><TextInput label="Suffisso titolo SEO" description="Compare dopo il titolo di ogni pagina" maxLength={contentLimits.site.titleSuffix} value={value.seo.titleSuffix} onChange={(event) => update((draft) => { draft.seo.titleSuffix = event.currentTarget.value; })} /><Textarea label="Descrizione SEO" description="Consigliati 120-155 caratteri" maxLength={contentLimits.site.description} autosize minRows={3} value={value.seo.defaultDescription} onChange={(event) => update((draft) => { draft.seo.defaultDescription = event.currentTarget.value; })} /><FieldCounter length={value.seo.defaultDescription.length} max={contentLimits.site.description} /><MediaPicker label="Immagine di condivisione" value={{ url: value.seo.shareImage ?? "", alt: "Immagine di condivisione" }} onChange={(next) => update((draft) => { draft.seo.shareImage = next.url || undefined; })} /><MediaPicker label="Favicon" value={{ url: value.identity.favicon ?? "", alt: "Favicon" }} onChange={(next) => update((draft) => { draft.identity.favicon = next.url || undefined; })} /></section>; }

function RevisionDrawer({ opened, onClose, resource, entity }: { opened: boolean; onClose: () => void; resource: AdminResource; entity: ContentEntity }) {
  const [revisions, setRevisions] = useState<RevisionSummary[] | null>(null);
  const [error, setError] = useState("");
  const [openDiff, setOpenDiff] = useState<string | null>(null);
  const [changes, setChanges] = useState<FieldChange[] | null>(null);
  useEffect(() => { if (opened) void adminApi.revisions(resource, entity.id).then(setRevisions).catch((reason) => setError(reason instanceof Error ? reason.message : "Revisioni non disponibili")); }, [opened, resource, entity.id]);
  const current = (entity.draft ?? entity.published) as Record<string, unknown> | undefined;
  const compare = async (revisionId: string) => {
    if (openDiff === revisionId) { setOpenDiff(null); return; }
    setOpenDiff(revisionId); setChanges(null);
    try { setChanges(diffContent(await adminApi.revision<Record<string, unknown>>(resource, entity.id, revisionId), current)); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Confronto non disponibile"); setOpenDiff(null); }
  };
  const restore = async (revisionId: string) => {
    if (!window.confirm("Ripristinare questa revisione come nuova bozza? La bozza attuale viene sostituita.")) return;
    try { await adminApi.restoreRevision(resource, entity.id, revisionId); notifications.show({ color: "teal", message: "Revisione ripristinata come nuova bozza." }); onClose(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Ripristino non riuscito"); }
  };
  return <Drawer opened={opened} onClose={onClose} title="Cronologia revisioni" position="right" size="md">
    {error && <Text c="red">{error}</Text>}
    {!revisions && !error && <Text c="dimmed">Caricamento…</Text>}
    <Stack gap="md">{revisions?.map((revision) => <div className="revision-entry" key={revision.id}>
      <div className="revision-row">
        <div><Text fw={700}>Versione {revision.revisionNumber}</Text><Text size="xs" c="dimmed">{new Date(revision.createdAt).toLocaleString("it-IT")} · {revision.createdBy}</Text></div>
        <Group gap="xs">
          {revision.isPublished && <Badge color="teal" variant="light">Pubblicata</Badge>}
          {revision.isDraft && <Badge color="gray" variant="light">Bozza</Badge>}
          <Button size="xs" variant="subtle" color="dark" onClick={() => void compare(revision.id)}>{openDiff === revision.id ? "Nascondi" : "Confronta"}</Button>
          <Button size="xs" variant="default" disabled={revision.isDraft} onClick={() => void restore(revision.id)}>Ripristina</Button>
        </Group>
      </div>
      {openDiff === revision.id && <RevisionDiff changes={changes} />}
    </div>)}</Stack>
  </Drawer>;
}
function RevisionDiff({ changes }: { changes: FieldChange[] | null }) {
  if (!changes) return <Text size="xs" c="dimmed" className="revision-diff-empty">Carico il confronto…</Text>;
  if (!changes.length) return <Text size="xs" c="dimmed" className="revision-diff-empty">Nessuna differenza con la versione che stai modificando.</Text>;
  return <dl className="revision-diff">{changes.map((change) => <div key={change.field}>
    <dt>{change.label}</dt>
    <dd><span className="diff-before">{change.before}</span><span className="diff-arrow" aria-hidden="true">→</span><span className="diff-after">{change.after}</span></dd>
  </div>)}</dl>;
}

function UserManagement({ users, currentEmail, onChanged }: { users: AdminUser[]; currentEmail: string; onChanged: () => Promise<void> }) { const form = useForm({ mode: "controlled", initialValues: { email: "", role: "editor" as "admin" | "editor" }, validate: { email: (value) => /^\S+@\S+\.\S+$/.test(value) ? null : "Email non valida" } }); const [saving, setSaving] = useState(false); const save = async (email: string, role: "admin" | "editor", active: boolean) => { setSaving(true); try { await adminApi.saveUser(email, role, active); await onChanged(); form.reset(); } catch (error) { notifications.show({ color: "red", message: error instanceof Error ? error.message : "Accesso non aggiornato" }); } finally { setSaving(false); } }; return <Stack gap="xl"><Text c="dimmed" size="sm">Il ruolo qui controlla il CMS. L’email deve restare anche nell’allow-list Cloudflare Access.</Text><form onSubmit={form.onSubmit(({ email, role }) => void save(email, role, true))}><Stack><TextInput label="Email" maxLength={254} {...form.getInputProps("email")} /><Select label="Ruolo CMS" data={["editor", "admin"]} {...form.getInputProps("role")} /><Button type="submit" color="orange" loading={saving}>Salva accesso</Button></Stack></form><Stack gap={0}>{users.map((user) => { const isSelf = user.email.trim().toLowerCase() === currentEmail.trim().toLowerCase(); return <div className="access-row" key={user.email}><div><Text fw={600}>{user.email}{isSelf && <Badge ml={8} size="xs" variant="light">Tu</Badge>}</Text><Text size="xs" c="dimmed">{isSelf ? "Il tuo accesso: modificalo da un altro amministratore." : user.active ? user.role : "Disattivato"}</Text></div><Group><Select aria-label={`Ruolo di ${user.email}`} size="xs" disabled={isSelf} data={["editor", "admin"]} value={user.role} onChange={(next) => void save(user.email, (next ?? "editor") as "admin" | "editor", user.active)} /><Button size="xs" variant="subtle" disabled={isSelf} color={user.active ? "red" : "teal"} onClick={() => void save(user.email, user.role, !user.active)}>{user.active ? "Disattiva" : "Riattiva"}</Button></Group></div>; })}</Stack></Stack>; }

function RichTextList({ label, values, onChange, maxLength = 600 }: { label: string; values: RichText[]; onChange: (values: RichText[]) => void; maxLength?: number }) { return <section className="rich-list"><Text fw={700} size="sm">{label}</Text>{values.map((value, index) => <div className="paragraph-edit" key={index}><RichTextField label={`Paragrafo ${index + 1}`} maxLength={maxLength} value={value} onChange={(next) => onChange(values.map((paragraph, itemIndex) => itemIndex === index ? next : paragraph))} />{values.length > 1 && <Button variant="subtle" color="red" size="compact-sm" onClick={() => { if (plainText(value).trim() && !window.confirm(`Eliminare il paragrafo ${index + 1}? Il testo va perso.`)) return; onChange(values.filter((_, itemIndex) => itemIndex !== index)); }}>Rimuovi paragrafo</Button>}</div>)}<Button variant="subtle" color="dark" size="compact-sm" onClick={() => onChange([...values, asRichText("")])}>+ Aggiungi paragrafo</Button></section>; }
const blockLabels: Record<ProjectBlock["type"], string> = { paragraph: "Testo", quote: "Citazione", list: "Elenco", image: "Immagine", stat: "Dato" };
function BlocksEditor({ blocks, onChange }: { blocks: ProjectBlock[]; onChange: (blocks: ProjectBlock[]) => void }) { const update = (index: number, next: ProjectBlock) => onChange(blocks.map((block, itemIndex) => itemIndex === index ? next : block)); const move = (index: number, direction: -1 | 1) => { const next = [...blocks]; const target = index + direction; if (!next[target]) return; [next[index], next[target]] = [next[target], next[index]]; onChange(next); }; const remove = (index: number, type: ProjectBlock["type"]) => { if (!window.confirm(`Eliminare il blocco ${index + 1} (${blockLabels[type].toLowerCase()})? Il contenuto va perso.`)) return; onChange(blocks.filter((_, itemIndex) => itemIndex !== index)); }; const add = (type: ProjectBlock["type"]) => { const id = crypto.randomUUID(); const block: ProjectBlock = type === "paragraph" ? { id, type, text: asRichText("") } : type === "quote" ? { id, type, text: asRichText("") } : type === "list" ? { id, type, title: "", items: [] } : type === "image" ? { id, type, src: "", alt: "" } : { id, type, value: "", label: "" }; onChange([...blocks, block]); }; return <section className="blocks"><Group justify="space-between"><Text fw={700}>Blocchi del racconto</Text><Menu><Menu.Target><Button variant="default" size="xs">Aggiungi blocco</Button></Menu.Target><Menu.Dropdown>{(["paragraph", "quote", "list", "image", "stat"] as const).map((type) => <Menu.Item key={type} onClick={() => add(type)}>{blockLabels[type]}</Menu.Item>)}</Menu.Dropdown></Menu></Group>{blocks.map((block, index) => <div className="block-edit" key={block.id}><Group justify="space-between"><Text size="xs" fw={700} tt="uppercase">{index + 1}. {blockLabels[block.type]}</Text><Group gap={2}><ActionIcon aria-label={`Sposta il blocco ${index + 1} più in alto`} variant="subtle" color="dark" disabled={index === 0} onClick={() => move(index, -1)}>↑</ActionIcon><ActionIcon aria-label={`Sposta il blocco ${index + 1} più in basso`} variant="subtle" color="dark" disabled={index === blocks.length - 1} onClick={() => move(index, 1)}>↓</ActionIcon><ActionIcon aria-label={`Elimina il blocco ${index + 1}`} variant="subtle" color="red" onClick={() => remove(index, block.type)}>×</ActionIcon></Group></Group>{block.type === "paragraph" && <RichTextField label="Testo" maxLength={contentLimits.project.paragraph} value={block.text} onChange={(text) => update(index, { ...block, text })} />}{block.type === "quote" && <Stack><RichTextField label="Citazione" maxLength={contentLimits.project.quote} value={block.text} onChange={(text) => update(index, { ...block, text })} /><TextInput label="Fonte" maxLength={contentLimits.project.quoteSource} value={block.source ?? ""} onChange={(event) => update(index, { ...block, source: event.currentTarget.value || undefined })} /></Stack>}{block.type === "list" && <Stack><TextInput label="Titolo elenco" maxLength={contentLimits.project.listTitle} value={block.title} onChange={(event) => update(index, { ...block, title: event.currentTarget.value })} /><Textarea label="Voci" description="Una riga per voce" maxLength={contentLimits.project.listItem * 12} autosize minRows={3} value={block.items.join("\n")} onChange={(event) => update(index, { ...block, items: lines(event.currentTarget.value) })} /></Stack>}{block.type === "image" && <Stack><MediaPicker label="Immagine" required value={{ url: block.src ?? "", alt: block.alt, assetId: block.assetId }} onChange={(next) => update(index, { ...block, src: next.url, alt: next.alt, assetId: next.assetId })} /><Textarea label="Didascalia" maxLength={contentLimits.project.imageCaption} autosize minRows={2} value={block.caption ?? ""} onChange={(event) => update(index, { ...block, caption: event.currentTarget.value || undefined })} /></Stack>}{block.type === "stat" && <div className="form-grid"><TextInput label="Valore" maxLength={contentLimits.project.statValue} value={block.value} onChange={(event) => update(index, { ...block, value: event.currentTarget.value })} /><TextInput label="Etichetta" maxLength={contentLimits.project.statLabel} value={block.label} onChange={(event) => update(index, { ...block, label: event.currentTarget.value })} /></div>}</div>)}</section>; }
function LinksEditor({ links, onChange }: { links: ProjectContent["links"]; onChange: (links: ProjectContent["links"]) => void }) { return <section className="repeatable-section"><Group justify="space-between"><Text fw={700}>Link del progetto</Text><Button variant="subtle" color="dark" size="compact-sm" onClick={() => onChange([...links, { label: "", href: "", kind: "website" }])}>+ Aggiungi link</Button></Group>{links.map((link, index) => <div className="activity-edit" key={`${link.href}-${index}`}><div className="form-grid"><TextInput label="Etichetta" maxLength={contentLimits.project.linkLabel} value={link.label} onChange={(event) => onChange(links.map((entry, itemIndex) => itemIndex === index ? { ...entry, label: event.currentTarget.value } : entry))} /><TextInput label="URL" maxLength={2_000} value={link.href} onChange={(event) => onChange(links.map((entry, itemIndex) => itemIndex === index ? { ...entry, href: event.currentTarget.value } : entry))} /><Select label="Tipo" data={["website", "instagram", "facebook", "materials"]} value={link.kind} onChange={(next) => onChange(links.map((entry, itemIndex) => itemIndex === index ? { ...entry, kind: (next ?? "website") as ProjectContent["links"][number]["kind"] } : entry))} /></div><Button variant="subtle" color="red" size="compact-sm" onClick={() => onChange(links.filter((_, itemIndex) => itemIndex !== index))}>Rimuovi link</Button></div>)}</section>; }
function VideoEditor({ value, onChange }: { value: ProjectContent["video"]; onChange: (value: ProjectContent["video"]) => void }) { const video = value ?? { provider: "youtube" as const, id: "", alt: "", thumbnail: "", caption: "" }; return <section className="repeatable-section"><Group justify="space-between"><Text fw={700}>Video</Text><Button variant="subtle" color={value ? "red" : "dark"} size="compact-sm" onClick={() => onChange(value ? undefined : video)}>{value ? "Rimuovi video" : "+ Aggiungi video"}</Button></Group>{value && <Stack><div className="form-grid"><Select label="Provider" data={["youtube", "vimeo"]} value={video.provider} onChange={(next) => onChange({ ...video, provider: (next ?? "youtube") as "youtube" | "vimeo" })} /><TextInput label="ID video" description="Solo ID, non URL completo" maxLength={64} value={video.id} onChange={(event) => onChange({ ...video, id: event.currentTarget.value })} /><TextInput label="Testo alternativo" maxLength={contentLimits.project.videoAlt} value={video.alt} onChange={(event) => onChange({ ...video, alt: event.currentTarget.value })} /><Textarea label="Didascalia" maxLength={contentLimits.project.videoCaption} autosize minRows={2} value={video.caption ?? ""} onChange={(event) => onChange({ ...video, caption: event.currentTarget.value || undefined })} /></div><MediaPicker label="Miniatura video" required value={{ url: video.thumbnail ?? "", alt: video.alt }} onChange={(next) => onChange({ ...video, thumbnail: next.url || undefined, alt: next.alt })} /></Stack>}</section>; }
function SocialLinks({ value, onChange }: { value: SiteSettingsContent["identity"]["socialLinks"]; onChange: (value: SiteSettingsContent["identity"]["socialLinks"]) => void }) { return <section className="repeatable-section"><Group justify="space-between"><Text fw={700}>Social</Text><Button variant="subtle" color="dark" size="compact-sm" onClick={() => onChange([...value, { label: "", href: "" }])}>+ Aggiungi social</Button></Group>{value.map((link, index) => <div className="activity-edit" key={`${link.href}-${index}`}><div className="form-grid"><TextInput label="Nome" maxLength={contentLimits.site.socialLabel} value={link.label} onChange={(event) => onChange(value.map((entry, itemIndex) => itemIndex === index ? { ...entry, label: event.currentTarget.value } : entry))} /><TextInput label="URL" maxLength={2_000} value={link.href} onChange={(event) => onChange(value.map((entry, itemIndex) => itemIndex === index ? { ...entry, href: event.currentTarget.value } : entry))} /></div><Button variant="subtle" color="red" size="compact-sm" onClick={() => onChange(value.filter((_, itemIndex) => itemIndex !== index))}>Rimuovi social</Button></div>)}</section>; }
function ReviewProject({ project }: { project: ProjectContent }) { return <div className="review-project"><Text className="eyebrow">Revisione</Text><h2>{project.title || "Titolo progetto"}</h2><Text c="dimmed">{project.subtitle || "Aggiungi un sottotitolo prima di salvare."}</Text><Group mt="lg"><Badge variant="light">{project.blocks.length} blocchi</Badge><Badge variant="light">{project.cover ? "Copertina pronta" : "Copertina mancante"}</Badge><Badge variant="light">{project.links.length} link</Badge></Group></div>; }
function PreviewRichText({ value }: { value: RichText }) { return <>{value.map((span, index) => { let content: React.ReactNode = span.text; if (span.marks?.includes("italic")) content = <em>{content}</em>; if (span.marks?.includes("highlight")) content = <mark>{content}</mark>; if (span.marks?.includes("link") && span.href) content = <a href={span.href}>{content}</a>; return <span key={`${span.text}-${index}`}>{content}</span>; })}</>; }
function previewCropStyle(member: TeamMemberContent) { const crop = member.imageCrop; if (!crop) return undefined; const focusX = crop.x + crop.width / 2; const focusY = crop.y + crop.height / 2; const zoom = Math.max(1, Math.min(3, 100 / Math.min(crop.width, crop.height))); return { objectPosition: `${focusX}% ${focusY}%`, transform: `scale(${zoom})`, transformOrigin: `${focusX}% ${focusY}%` }; }
function ProjectPreview({ project }: { project: ProjectContent }) { return <article className="preview-project preview-project-detail"><section className="preview-project-hero">{project.cover ? <img src={project.cover} alt={project.coverAlt} /> : <div className="preview-image-empty">Aggiungi una copertina</div>}<div className="preview-project-shade" /><div className="preview-project-title"><Text className="eyebrow">{project.statusLabel} {project.themes[0] && `— ${project.themes[0]}`}</Text><h1>{project.title || "Titolo progetto"}</h1><p>{project.subtitle || "Il sottotitolo comparirà qui."}</p></div></section><section className="preview-project-overview"><div><Text className="eyebrow">Il progetto</Text><h2><PreviewRichText value={project.intro} /></h2></div><dl><div><dt>Periodo</dt><dd>{project.dateRange || "—"}</dd></div><div><dt>Luogo</dt><dd>{project.location || "—"}</dd></div><div><dt>Per chi</dt><dd>{project.audience || "—"}</dd></div></dl></section><section className="preview-project-story"><Text className="eyebrow">L’intenzione</Text><p className="preview-objective"><PreviewRichText value={project.objective} /></p>{project.blocks.map((block) => <div className={`preview-block preview-block-${block.type}`} key={block.id}>{block.type === "paragraph" && <p><PreviewRichText value={block.text} /></p>}{block.type === "quote" && <blockquote><p><PreviewRichText value={block.text} /></p>{block.source && <cite>{block.source}</cite>}</blockquote>}{block.type === "list" && <><h3>{block.title}</h3><ul>{block.items.map((item) => <li key={item}>{item}</li>)}</ul></>}{block.type === "image" && <figure>{block.src && <img src={block.src} alt={block.alt} />}{block.caption && <figcaption>{block.caption}</figcaption>}</figure>}{block.type === "stat" && <p className="preview-stat"><strong>{block.value}</strong><span>{block.label}</span></p>}</div>)}</section>{project.outcomes.length > 0 && <section className="preview-outcomes"><Text className="eyebrow">Cosa abbiamo attivato</Text>{project.outcomes.map((outcome, index) => <p key={outcome}><b>0{index + 1}</b>{outcome}</p>)}</section>}</article>; }
function TeamPreview({ member }: { member: TeamMemberContent }) { return <article className="preview-project preview-team"><section className="preview-team-hero"><div className="preview-team-image">{member.image ? <img src={member.image} alt={`Ritratto di ${member.name}`} style={previewCropStyle(member)} /> : <div className="preview-image-empty">Aggiungi un ritratto</div>}</div><div><Text className="eyebrow">Persone</Text><h1>{member.name || "Nome persona"}</h1><p>{member.role || "Ruolo"}</p></div></section><section className="preview-team-copy">{member.bio.map((paragraph, index) => <p key={index}><PreviewRichText value={paragraph} /></p>)}{plainText(member.quote) && <blockquote><p><PreviewRichText value={member.quote} /></p>{member.quoteAuthor && <cite>{member.quoteAuthor}</cite>}</blockquote>}</section></article>; }
function SitePreview({ site }: { site: SiteSettingsContent }) { return <article className="preview-project preview-site"><section className="preview-site-hero" style={site.home.hero.heroImage ? { backgroundImage: `linear-gradient(90deg, rgba(18, 42, 48, .88), rgba(18, 42, 48, .24)), url(${site.home.hero.heroImage})` } : undefined}><Text className="eyebrow">{site.home.hero.meta}</Text><h1><PreviewRichText value={site.home.hero.headline} /></h1><button type="button">{site.home.hero.ctaLabel}</button></section><section className="preview-site-association"><Text className="eyebrow">Associazione</Text><h2><PreviewRichText value={site.home.association.heading} /></h2><p><PreviewRichText value={site.home.association.body} /></p></section><section className="preview-site-origin"><Text className="eyebrow">{site.home.origin.eyebrow}</Text><h2><PreviewRichText value={site.home.origin.heading} /></h2><p><PreviewRichText value={site.home.origin.statement} /></p></section><section className="preview-site-footer"><b>{site.identity.organizationName}</b><span>{site.identity.email}</span></section></article>; }
